from itertools import chain, combinations

def is_valid(subset):
    sorted_s = sorted(subset)
    for i in range(len(sorted_s) - 1):
        if sorted_s[i+1] == sorted_s[i] + 1:
            return False
    return True

def solve():
    s = set(range(1, 11))
    count = 0
    # Power set generation
    for i in range(len(s) + 1):
        for subset in combinations(s, i):
            if is_valid(subset):
                if sum(subset) % 2 == 0:
                    count += 1
    return count

print(solve())
"

