    s = set(range(1, 11))
    count = 0
    # Iterate through all possible subsets
    for i in range(1 << 10):
        subset = [j + 1 for j in range(10) if (i >> j) & 1]
        if is_valid(subset):
            if sum(subset) % 2 == 0:
                count += 1
    return count

